  console.warn("CreatePanelController: root not found");
  return;
}

const objs = ${JSON.stringify(objects)};
const byId = {};

objs.forEach(cfg => {
  let el = document.getElementById(cfg.id);
  if (!el) {
    el = document.createElement(cfg.type === "button" ? "button" : "div");
    el.id = cfg.id;
    byId[cfg.id] = el;
  } else {
    byId[cfg.id] = el;
  }

  el.style.position = "fixed";
  el.style.left = (cfg.x ?? 0) + "px";
  el.style.top  = (cfg.y ?? 0) + "px";
  el.style.width  = (cfg.width  ?? 50) + "px";
  el.style.height = (cfg.height ?? 50) + "px";
  el.style.backgroundColor = cfg.color || "gray";
  el.style.zIndex = cfg.zIndex ?? "1000";
  el.style.borderRadius = cfg.type === "button" ? "8px" : "0";
  el.style.cursor = cfg.type === "button" ? "pointer" : "default";

  if (cfg.label && !el.textContent) {
    el.textContent = cfg.label;
  }

  let parentEl = root;
  if (cfg.parent) {
    parentEl = document.getElementById(cfg.parent) || root;
  }
  if (!el.parentElement) {
    parentEl.appendChild(el);
  }

  if (cfg.onclick) {
    const onclickCfg = cfg.onclick; // ← 這裡直接用 cfg.onclick

    el.onclick = async function(ev) {
      ev.stopPropagation();
      try {
        if (onclickCfg.type === "fetch") {
          const url = onclickCfg.url;
          const options = {
            method: onclickCfg.method || "GET",
            headers: { "Content-Type": "application/json" }
          };
          if (onclickCfg.body) {
            options.body = JSON.stringify(onclickCfg.body);
          } else if (onclickCfg.params) {
            const params = new URLSearchParams(onclickCfg.params).toString();
            window.open(url + (url.includes('?') ? '&' : '?') + params, '_blank');
            return;
          }
          const resp = await fetch(url, options);
          let data;
          try {
            data = await resp.json();
          } catch (e) {
            data = await resp.text();
          }
          console.log("Fetch result:", data);
        } else if (onclickCfg.type === "js") {
          eval(onclickCfg.code);
        } else if (onclickCfg.type === "url") {
          window.open(onclickCfg.url, '_blank');
        }
      } catch (err) {
        console.error("Button", cfg.id, "error:", err);
      }
    };
  }
});
`;

  return {
    status: "ready",
    clientJS
  };
}

