async function processRequest(input) {
  const objects = input.var.objects || [];

  const rootSelector = "#ms-apiresults-body";

  console.log("CreatePanelController running(A)", objects);

  const clientJS = `
console.log("CreatePanelController running(B)");

const root = document.querySelector(${JSON.stringify(rootSelector)});
if (!root) {
  console.warn("CreatePanelController: root not found");
  return;
}

const objs = ${JSON.stringify(objects)};
const byId = {};

objs.forEach(cfg => {
  let el = document.getElementById(cfg.id);
  if (!el) {
    el = document.createElement(cfg.type === "button" ? "button" : "div");
    el.id = cfg.id;
    byId[cfg.id] = el;
  } else {
    byId[cfg.id] = el;
  }

  el.style.position = "fixed";
  el.style.left = (cfg.x ?? 0) + "px";
  el.style.top  = (cfg.y ?? 0) + "px";
  el.style.width  = (cfg.width  ?? 50) + "px";
  el.style.height = (cfg.height ?? 50) + "px";
  el.style.backgroundColor = cfg.color || "gray";
  el.style.zIndex = cfg.zIndex ?? "1000";
  el.style.borderRadius = cfg.type === "button" ? "8px" : "0";
  el.style.cursor = cfg.type === "button" ? "pointer" : "default";

  if (cfg.label && !el.textContent) {
    el.textContent = cfg.label;
  }

  let parentEl = root;
  if (cfg.parent) {
    parentEl = document.getElementById(cfg.parent) || root;
  }
  if (!el.parentElement) {
    parentEl.appendChild(el);
  }

  if (cfg.onclick) {
    const onclickCfg = cfg.onclick; // ← 這裡直接用 cfg.onclick

    el.onclick = async function(ev) {
      ev.stopPropagation();
      try {
        if (onclickCfg.type === "fetch") {
          const url = onclickCfg.url;
          const options = {
            method: onclickCfg.method || "GET",
            headers: { "Content-Type": "application/json" }
          };
          if (onclickCfg.body) {
            options.body = JSON.stringify(onclickCfg.body);
          } else if (onclickCfg.params) {
            const params = new URLSearchParams(onclickCfg.params).toString();
            window.open(url + (url.includes('?') ? '&' : '?') + params, '_blank');
            return;
          }
          const resp = await fetch(url, options);
          let data;
          try {
            data = await resp.json();
          } catch (e) {
            data = await resp.text();
          }
          console.log("Fetch result:", data);
        } else if (onclickCfg.type === "js") {
          eval(onclickCfg.code);
        } else if (onclickCfg.type === "url") {
          window.open(onclickCfg.url, '_blank');
        }
      } catch (err) {
        console.error("Button", cfg.id, "error:", err);
      }
    };
  }
});
`;

  return {
    status: "ready",
    clientJS
  };
}

// MoveObjectsController
async function processRequest(input) {
  console.log("move objects", input);
  const objects = input.var?.objectActions || [];

  const clientJS = `
    const configs = ${JSON.stringify(objects)};

    console.log("MoveObjectsController start", configs);

    if (!Array.isArray(configs) || configs.length === 0) {
      console.warn("MoveObjectsController: no objects");
      return;
    }

    const items = [];

    configs.forEach(cfg => {
      if (!cfg || !cfg.selector) return;
      let el = document.getElementById(cfg.selector);  // Use selector as ID
      if (!el) {
        console.warn("MoveObjectsController: element not found", cfg.selector);
        return;
      }

      const style = window.getComputedStyle(el);
      if (style.position === "static") {
        el.style.position = "absolute";
      }

      const rect = el.getBoundingClientRect();
      const startX = rect.left + window.scrollX;
      const startY = rect.top + window.scrollY;

      const targetX = cfg.targetX ?? startX;
      const targetY = cfg.targetY ?? startY;
      const speed = cfg.speed ?? 200;  // px/s

      items.push({
        el, startX, startY, targetX, targetY, speed, done: false
      });
    });

    if (items.length === 0) {
      console.warn("MoveObjectsController: no valid items");
      return;
    }

    let startTime = null;

    function step(timestamp) {
      if (!startTime) startTime = timestamp;
      const elapsed = (timestamp - startTime) / 1000;

      let allDone = true;

      items.forEach(item => {
        if (item.done) return;

        const dx = item.targetX - item.startX;
        const dy = item.targetY - item.startY;
        const distance = Math.sqrt(dx * dx + dy * dy);
        if (distance === 0) {
          item.done = true;
          return;
        }

        const duration = distance / item.speed;
        const t = Math.min(elapsed / duration, 1);

        const x = item.startX + dx * t;
        const y = item.startY + dy * t;

        item.el.style.left = x + "px";
        item.el.style.top = y + "px";

        if (t >= 1) {
          item.done = true;
        } else {
          allDone = false;
const resp = fetch('http://localhost:3001/run/main');
        }
      });

      if (!allDone) {
        window.requestAnimationFrame(step);
      }
    }

    window.requestAnimationFrame(step);
  `;

const resp = fetch('http://localhost:3001/run/Game1runner');
  return {
    status: "ready",
    clientJS,
  };
}

