// CreateObjectsController
async function processRequest(input) {
  const rootSelector = "#ms-apiresults-body";

  const existingMoveObjects = getVar("objects") || [];

  const objects = input.var.objects;

  const newMoveObjects = objects
    .filter(o => {
      const existingSelector = existingMoveObjects.find(obj => obj.selector === `#${o.id}`);
      return !existingSelector;
    })
    .map(o => ({
      selector: `#${o.id}`,
      x: o.x,
      y: o.y,
      speed: o.speed ?? 200,
    }));

  const moveObjects = [...existingMoveObjects, ...newMoveObjects];
  setVar("objects", moveObjects);

  const clientJS = `
console.log("CreateObjectsController running");

const root = document.querySelector(${JSON.stringify(rootSelector)});
if (!root) {
  console.warn("CreateObjectsController: root not found");
  return;
}

const objs = ${JSON.stringify(objects)};

objs.forEach(cfg => {
  let el = document.getElementById(cfg.id);
  if (!el) {
    el = document.createElement("div");
    el.id = cfg.id;
    root.appendChild(el);
  }

  el.style.position = "fixed";
  el.style.left = cfg.x + "px";
  el.style.top  = cfg.y + "px";
  el.style.width  = (cfg.width  ?? 50) + "px";
  el.style.height = (cfg.height ?? 50) + "px";
  el.style.backgroundColor = cfg.color || "gray";
  el.style.zIndex = cfg.zIndex != null ? String(cfg.zIndex) : "1000";
});
`;

  const resp = fetch('http://localhost:3001/next/'+ input.runId);


  return {
    status: "ready",
    clientJS,
  };
}

